window.FILM_WORK_PROMPTS={"work_id":"src-908c1763f1d81fa6","records":[{"work_id":"src-908c1763f1d81fa6","frame_id":"FG-8abacedd3c0d9bdb","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/07 (291).jpg","source_page":"https://film-grab.com/2014/09/24/daughters-of-darkness/","scene":"灰紫色调的海滨城市全景，前景是空旷沙滩与成排白色小屋，中景为拱廊建筑与街道，背景矗立着高层公寓楼，天空阴沉。","analysis":"画面采用广角远景构图，沙滩占据前景约三分之一，白色小屋呈对角线排列引导视线。中景拱廊建筑横向延伸，背景高楼垂直耸立，形成几何对比。整体光线昏暗，色彩饱和度极低，呈现冷灰紫色调，天空云层厚重，无明显直射光源，营造出压抑、静谧的氛围。","prompt":"灰紫色调的海滨城市全景，前景是空旷沙滩与成排白色小屋，中景为拱廊建筑与街道，背景矗立着高层公寓楼，天空阴沉。画面采用广角远景构图，沙滩占据前景约三分之一，白色小屋呈对角线排列引导视线。中景拱廊建筑横向延伸，背景高楼垂直耸立，形成几何对比。整体光线昏暗，色彩饱和度极低，呈现冷灰紫色调，天空云层厚重，无明显直射光源，营造出压抑、静谧的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T14:54:33-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/07 (291).jpg","observed_dimensions":[1200,720],"source_thumbnail_dimensions":[500,300],"source_image_match_mae":0.523,"observed_resolution":"normal","observation_limits":[],"id":"VP-3e3c64d21c7213cc","origin":"visual"},{"work_id":"src-908c1763f1d81fa6","frame_id":"FG-4c243ef0e26ab5a5","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/20 (296).jpg","source_page":"https://film-grab.com/2014/09/24/daughters-of-darkness/","scene":"黄昏时分，粉紫色天空布满细碎云层，右侧及下方为深色建筑剪影，太阳在建筑转角处发出耀眼白光，形成强烈逆光效果。","analysis":"构图采用对角线分割，建筑轮廓从右下向左上延伸，占据画面约60%面积。天空占据左上部分，呈现粉紫渐变色调。太阳位于建筑边缘，产生明显光晕和镜头眩光。建筑完全处于剪影状态，细节不可见，仅能辨认出窗户和屋顶轮廓。整体明暗对比强烈，色彩以冷调粉紫为主。","prompt":"黄昏城市建筑剪影，粉紫色天空布满细碎云层，太阳在建筑转角处发出耀眼白光，建筑呈现深色轮廓占据画面右侧和下方，窗户和屋顶线条清晰可辨，天空呈现粉紫到淡蓝的渐变色调，强烈的逆光效果产生光晕，建筑与天空形成鲜明对比，整体氛围宁静而略带忧郁，城市天际线在暮色中显得庄重而神秘","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T14:54:40-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/20 (296).jpg","observed_dimensions":[1200,720],"source_thumbnail_dimensions":[500,300],"source_image_match_mae":0.47,"observed_resolution":"normal","observation_limits":[],"id":"VP-975e046d5cb62a14","origin":"visual"},{"work_id":"src-908c1763f1d81fa6","frame_id":"FG-898993e59f8268e4","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/33 (295).jpg","source_page":"https://film-grab.com/2014/09/24/daughters-of-darkness/","scene":"前景右侧为模糊的金发人物背影，身着红色衣物。背景左侧门框处站立一名裸体短发人物，室内可见红色躺椅、小桌及暖色台灯。","analysis":"构图采用前景虚化与背景清晰对比，右侧红衣人物占据约三分之一画面，形成窥视视角。左侧人物全身可见，站立于门边。室内光线偏暖，台灯发出橙红色光晕，照亮墙面与家具，与前景冷色调形成反差。","prompt":"电影质感静帧，前景右侧为失焦的金发人物背影，身穿红色露背上衣，占据画面右侧。背景左侧门框处，一名短发裸体人物站立，身体微侧。室内环境铺有红色花纹地毯，放置一张红色软垫躺椅，旁边小桌上有一盏发出橙红色光晕的台灯。墙面挂有深色画框，整体色调呈现暖红与冷绿的对比，光影层次丰富。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T14:54:47-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/33 (295).jpg","observed_dimensions":[1200,720],"source_thumbnail_dimensions":[500,300],"source_image_match_mae":0.516,"observed_resolution":"normal","observation_limits":[],"id":"VP-94ac2ac584e62574","origin":"visual"},{"work_id":"src-908c1763f1d81fa6","frame_id":"FG-1cc3b322d4e4f13f","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/46 (287).jpg","source_page":"https://film-grab.com/2014/09/24/daughters-of-darkness/","scene":"昏暗浴室内部，一名裸体人物俯卧在大理石洗手台下方的地面上，左侧可见白色浴缸边缘，上方是双盆洗手台及镜面，地面散落着杂物。","analysis":"采用高角度俯视构图，画面主体为俯卧在地的人物，其背部、臀部及双腿完全可见，头部朝向右侧。人物位于画面中下方，上方占据较大比例的是深色大理石双盆洗手台及镜面反射。环境光线极暗，主要光源来自上方，照亮了人物背部和洗手台表面，形成强烈的明暗对比，整体色调偏冷且压抑。","prompt":"高角度俯视镜头，昏暗的浴室内部场景。画面中心偏下，一名裸体人物俯卧在浅色地砖上，背部朝上，双腿自然伸展，头部偏向右侧。人物上方是一张深色大理石双盆洗手台，台面上有两个白色圆形洗手盆，后方是大面积镜面，反射出模糊的室内景象。画面左侧前景是白色浴缸的边缘，内部可见少量深色污渍。地面散落着一些难以辨认的杂物和碎片。整体光线昏暗，主要光源来自上方，照亮了人物背部和洗手台，周围环境笼罩在深沉的阴影中，色调偏冷，营造出压抑、静谧的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T14:54:55-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/46 (287).jpg","observed_dimensions":[1200,720],"source_thumbnail_dimensions":[500,300],"source_image_match_mae":0.49,"observed_resolution":"normal","observation_limits":[],"id":"VP-a51ec6490f17dfcf","origin":"visual"},{"work_id":"src-908c1763f1d81fa6","frame_id":"FG-e89e1f82bf83ed10","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/59 (257).jpg","source_page":"https://film-grab.com/2014/09/24/daughters-of-darkness/","scene":"深红色地毯上，一名穿红衣的人物仰面平躺，四肢舒展。其上方有一名穿银色亮片裙的人物俯身压在其身上，右侧还有一名穿白衣的人物侧卧，周围散落着破碎的盘碟。","analysis":"画面采用高角度俯视构图，主体为三名纠缠的人物。红衣人物全身可见，占据画面中心；银衣人物仅见躯干与背部，俯身姿态；白衣人物侧卧于右下，头部朝向画面下方。环境为深红色花纹地毯，左上角散落着白色碎盘与食物残渣。光线昏暗，色彩以深红、银白和亮红为主，明暗对比强烈，营造出压抑且混乱的视觉氛围。","prompt":"高角度俯视镜头，深红色花纹地毯铺满地面。画面中央一名穿红色长袖连衣裙的人物仰面平躺，双腿微曲，赤足，身体舒展。其上方一名穿银色亮片紧身裙的人物俯身压在其胸腹部，背部朝向镜头。画面右侧一名穿白色宽松上衣的人物侧卧，头部靠近红衣人物腿部。左上角地毯上散落着破碎的白色瓷盘、玻璃器皿和食物残渣。整体色调偏暗，以深红和银白为主，光影对比强烈，呈现出一种混乱、纠缠且压抑的视觉状态。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T14:55:03-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/59 (257).jpg","observed_dimensions":[1200,720],"source_thumbnail_dimensions":[500,300],"source_image_match_mae":0.477,"observed_resolution":"normal","observation_limits":[],"id":"VP-5eef8f7a35e244af","origin":"visual"},{"work_id":"src-908c1763f1d81fa6","frame_id":"FG-e01b82c4c7b299b5","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/08 (291).jpg","source_page":"https://film-grab.com/2014/09/24/daughters-of-darkness/","scene":"一位身穿白色长毛皮大衣的金发女子背对镜头站立在豪华大厅左侧，右侧前景有一张摆放着粉色花束的雕花桌，背景是宏伟的楼梯和拱门。","analysis":"画面采用横向构图，前景人物与右侧花桌形成视觉平衡。左侧女子全身可见，身形修长，占据画面约三分之一高度；右侧花桌占据前景右侧，花瓶中的粉色花朵色彩鲜艳。背景深处可见楼梯及两名模糊人影。整体光线柔和偏暗，色调呈暖褐色，营造出一种静谧、复古且略带神秘的氛围。","prompt":"一位身穿白色长毛皮大衣、脚踩白色短靴的金发女子背对镜头站立在画面左侧，肩背白色手袋。右侧前景是一张深色雕花桌，桌上摆放着盛满粉色花朵的蓝白瓷花瓶。背景是宏伟的欧式大厅，拥有高大的拱门、立柱和铺着地毯的楼梯，楼梯处有模糊人影。地面铺着深色花纹地毯，整体色调偏暖褐，光线柔和，呈现出复古且静谧的室内氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T17:08:43+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/08 (291).jpg","observed_dimensions":[1200,720],"source_thumbnail_dimensions":[500,300],"source_image_match_mae":0.533,"observed_resolution":"normal","observation_limits":[],"id":"VP-1419814e154f8c0d","origin":"visual"},{"work_id":"src-908c1763f1d81fa6","frame_id":"FG-6271fdde1af1ad7a","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/21 (296).jpg","source_page":"https://film-grab.com/2014/09/24/daughters-of-darkness/","scene":"室内卧室场景，一男一女并排坐在铺着棕色床单的大床上，床前摆放着托盘，两侧墙壁对称设有装饰性小桌和灯具。","analysis":"画面采用正面平视构图，床铺占据画面下半部约三分之二空间，人物位于画面中上部。两人上半身及腿部可见，脚部伸出被单外。左侧人物穿红色上衣，右侧人物穿深色上衣。光线柔和均匀，无明显强光源方向，整体色调偏暖，墙面为浅粉色，床品为棕色，地毯为深红色。","prompt":"室内卧室，正面平视视角，一男一女并排坐在白色雕花床头的大床上，床铺宽大，棕色床单覆盖床面，两人脚部伸出被单外。左侧人物穿红色长袖上衣，右侧人物穿深色长袖上衣，两人面前床面上放着托盘和杯具。床两侧对称摆放深色雕花小桌，桌上各有一盏台灯。墙面为浅粉色，挂有圆形装饰画，地面铺深红色地毯。光线柔和，色调温暖，整体氛围安静私密。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T17:10:51+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/21 (296).jpg","observed_dimensions":[1200,720],"source_thumbnail_dimensions":[500,300],"source_image_match_mae":0.505,"observed_resolution":"normal","observation_limits":[],"id":"VP-39596803cf1c0f96","origin":"visual"},{"work_id":"src-908c1763f1d81fa6","frame_id":"FG-914169b939ce2990","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/34 (295).jpg","source_page":"https://film-grab.com/2014/09/24/daughters-of-darkness/","scene":"昏暗蓝调环境中，一名浅色卷发人物位于左侧，面部与肩部可见，右侧有模糊的浅色物体或肢体轮廓，背景深暗。","analysis":"人物占据画面左侧约三分之一，右侧大面积留白与模糊色块。整体处于极低照度下，仅人物面部与发丝有微弱高光，呈现冷蓝色调。视角平视，景深极浅，背景完全隐没于黑暗，人物轮廓边缘柔和，右侧模糊区域与主体形成虚实对比。","prompt":"极暗环境下的冷蓝色调画面，左侧一名浅色卷发人物，面部轮廓在微弱光线下隐约可见，眼神凝视前方，肩部覆盖着蓬松的浅色毛绒或羽毛状材质。画面右侧是大片模糊的深色背景与一个失焦的浅色块状轮廓。整体光线极弱，仅照亮人物面部局部与发丝边缘，其余部分沉入深蓝黑色的阴影中，营造出朦胧、神秘且压抑的视觉氛围，景深极浅，焦点集中在左侧人物面部。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T17:11:39+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/34 (295).jpg","observed_dimensions":[1200,720],"source_thumbnail_dimensions":[500,300],"source_image_match_mae":0.496,"observed_resolution":"normal","observation_limits":[],"id":"VP-abac2499b71f510e","origin":"visual"},{"work_id":"src-908c1763f1d81fa6","frame_id":"FG-39e222fd2b012563","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/47 (282).jpg","source_page":"https://film-grab.com/2014/09/24/daughters-of-darkness/","scene":"画面主体为一只睁开的眼睛及周围面部皮肤，占据绝大部分视野，背景为暗色模糊区域，无其他可见物体或环境细节。","analysis":"构图极度紧凑，仅呈现眼部及周围皮肤，人物身体其他部分不可见。视角平视，光线昏暗，整体色调偏冷紫。眼部细节清晰，瞳孔中有微弱反光，皮肤纹理在低光下隐约可见，明暗对比强烈，营造出一种沉静而专注的视觉感受。","prompt":"生成一张极度特写的人像画面，主体为一只睁开的眼睛，占据画面中心及大部分区域。人物面部皮肤呈现冷紫色调，光线昏暗，仅眼部有微弱高光。瞳孔深邃，内有细小反光点，睫毛清晰可见。周围皮肤纹理在低光下隐约显现，背景完全虚化为暗色块。整体氛围沉静、专注，无其他物体或环境元素干扰，强调眼部细节与光影对比。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T17:12:01+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/47 (282).jpg","observed_dimensions":[1200,720],"source_thumbnail_dimensions":[500,300],"source_image_match_mae":0.523,"observed_resolution":"normal","observation_limits":[],"id":"VP-d79fd903c1026b3b","origin":"visual"},{"work_id":"src-908c1763f1d81fa6","frame_id":"FG-44cbd43b1b78c1de","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/60 (255).jpg","source_page":"https://film-grab.com/2014/09/24/daughters-of-darkness/","scene":"深蓝色背景中，中心位置呈现粉紫色交叉光束，形成X形结构，周围伴有模糊光晕与散景亮点，整体画面处于失焦状态。","analysis":"构图以中心对称为主，两条粉紫色光带在画面中央交叉，形成明显的X形视觉焦点。画面整体严重失焦，边缘呈现柔和的蓝色渐变，中心区域亮度较高，带有粉紫色调。光带周围分布着数个模糊的圆形光斑，增强了光线的散射感。","prompt":"深蓝色背景，画面中心为粉紫色交叉光束，呈X形分布，光线柔和且边缘模糊。中心交叉点亮度最高，向四周逐渐过渡为淡蓝色。画面带有明显的失焦效果，光带周围散布着几个模糊的圆形光斑，整体色调偏冷，呈现出一种朦胧、梦幻的视觉氛围，无具体人物或物体轮廓。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T17:12:15+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/60 (255).jpg","observed_dimensions":[1200,720],"source_thumbnail_dimensions":[500,300],"source_image_match_mae":0.5,"observed_resolution":"normal","observation_limits":[],"id":"VP-5897829a9dc6f030","origin":"visual"}]};